# FraudAlert: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Fraudalert:
    alert_id: str = None  # ID
    payment_id: str = None  # FK
    rule: str = None  # Rule fired
    score: float = None  # 0-100
    status: str = None  # open/confirmed/false-positive

REQUIRED = ["alert_id", "payment_id", "rule", "score"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'alert_id': 'FA-11882', 'payment_id': 'P-7712001', 'rule': 'velocity-5x-baseline', 'score': 82, 'status': 'open'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

# ExchangeRate: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Exchangerate:
    pair: str = None  # e.g. EURUSD
    rate: float = None  # Rate
    quoted_at: str = None  # ISO 8601
    source: str = None  # Source

REQUIRED = ["pair", "rate", "quoted_at", "source"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'pair': 'EURUSD', 'rate': 1.0842, 'quoted_at': '2026-06-01T12:00:00Z', 'source': 'ECB'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))
